import{_ as a,o as t,c as n,ao as i}from"./chunks/framework.CIBJwm-3.js";const u=JSON.parse('{"title":"Manual — reading path","description":"","frontmatter":{},"headers":[],"relativePath":"manual/index.md","filePath":"manual/index.md","lastUpdated":null}'),l={name:"manual/index.md"};function o(s,e,r,d,h,c){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="man-index" tabindex="-1">Manual — reading path <a class="header-anchor" href="#man-index" aria-label="Permalink to &quot;Manual — reading path {#man-index}&quot;">​</a></h1><p>The Manual answers <em>how do I do this</em>. It says what to call, what the arguments mean, and where each choice bites. The <strong>why</strong> is in <a href="/MeanFieldHomogenization.jl/dev/theory/index#th-index">Theory — reading path</a>, and the exhaustive signatures are in the API section, which the pages here link into rather than repeat.</p><p>If you have never used the package, <a href="/MeanFieldHomogenization.jl/dev/manual/installation#man-installation">Installation</a> and then <a href="/MeanFieldHomogenization.jl/dev/manual/schemes#man-schemes">Schemes and RVEs</a> are the two pages that make everything else readable.</p><h2 id="Inclusions:-which-page-for-which-morphology" tabindex="-1">Inclusions: which page for which morphology <a class="header-anchor" href="#Inclusions:-which-page-for-which-morphology" aria-label="Permalink to &quot;Inclusions: which page for which morphology {#Inclusions:-which-page-for-which-morphology}&quot;">​</a></h2><p>Everything a scheme needs from a phase is one response tensor. What differs between the pages below is <em>how</em> that tensor is obtained — a closed form, a recurrence, a mesh, a network — and every one of them ends up in the same <code>add_phase!</code> call.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Your morphology</th><th style="text-align:left;">Page</th><th style="text-align:left;">How the response is obtained</th></tr></thead><tbody><tr><td style="text-align:left;">an ellipsoid, or one of its limits</td><td style="text-align:left;"><a href="/MeanFieldHomogenization.jl/dev/manual/ellipsoidal_inclusions#man-ellipsoidal-inclusions">Ellipsoidal inclusions</a></td><td style="text-align:left;">Eshelby&#39;s closed form</td></tr><tr><td style="text-align:left;">a fiber, a cylinder</td><td style="text-align:left;"><a href="/MeanFieldHomogenization.jl/dev/manual/cylindrical_inclusions#man-cylindrical-inclusions">Cylindrical inclusions</a></td><td style="text-align:left;">the same, in the cylindrical limit</td></tr><tr><td style="text-align:left;">a crack, a family of cracks</td><td style="text-align:left;"><a href="/MeanFieldHomogenization.jl/dev/manual/cracks#man-cracks">Cracks</a></td><td style="text-align:left;">the crack-opening tensor and its algebra</td></tr><tr><td style="text-align:left;">a coated particle, an interphase</td><td style="text-align:left;"><a href="/MeanFieldHomogenization.jl/dev/manual/layered_inclusions#man-layered">Layered inclusions</a></td><td style="text-align:left;">a recurrence over the layers</td></tr><tr><td style="text-align:left;">anything else, from your own code</td><td style="text-align:left;"><a href="/MeanFieldHomogenization.jl/dev/manual/custom_inclusions#man-custom-inclusions">Custom inclusions</a></td><td style="text-align:left;">you supply it, through one of three gates</td></tr><tr><td style="text-align:left;">a shape with no closed form</td><td style="text-align:left;"><a href="/MeanFieldHomogenization.jl/dev/manual/fe_inclusions#man-fe-inclusions">Finite-element inclusions</a></td><td style="text-align:left;">one Eshelby cell, solved</td></tr><tr><td style="text-align:left;">the same, but cheap and differentiable</td><td style="text-align:left;"><a href="/MeanFieldHomogenization.jl/dev/manual/neural_inclusions#man-neural-inclusions">Neural-surrogate inclusions</a></td><td style="text-align:left;">a network trained on it</td></tr></tbody></table><p><a href="/MeanFieldHomogenization.jl/dev/manual/inclusion_gallery#man-inclusion-gallery">The inclusion gallery</a> draws them, if you would rather recognize a shape than read a table.</p><h2 id="The-rest" tabindex="-1">The rest <a class="header-anchor" href="#The-rest" aria-label="Permalink to &quot;The rest {#The-rest}&quot;">​</a></h2><ul><li><p><strong><a href="/MeanFieldHomogenization.jl/dev/manual/schemes#man-schemes">Schemes and RVEs</a></strong> — building a cell, choosing an estimate, and what each scheme assumes. Then <a href="/MeanFieldHomogenization.jl/dev/manual/particle_assemblies#man-assemblies">particle assemblies</a> for a population rather than a phase, and <a href="/MeanFieldHomogenization.jl/dev/manual/multiscale#man-multiscale">multiscale</a> for a cell inside a cell.</p></li><li><p><strong><a href="/MeanFieldHomogenization.jl/dev/manual/laminates#man-laminates">Laminates</a></strong> — periodic homogenization, exact rather than estimated, and a different construction from everything above.</p></li><li><p><strong>Beyond elasticity</strong> — <a href="/MeanFieldHomogenization.jl/dev/manual/conductivity#man-conductivity">conduction</a>, <a href="/MeanFieldHomogenization.jl/dev/manual/viscoelasticity#man-viscoelasticity">viscoelasticity</a> with its <a href="/MeanFieldHomogenization.jl/dev/manual/rheological_models#man-rheological-models">rheological models</a> and <a href="/MeanFieldHomogenization.jl/dev/manual/laplace_inversion#man-laplace-inversion">Laplace–Carson inversion</a>, and <a href="/MeanFieldHomogenization.jl/dev/manual/poromechanics#manual-poromechanics">poromechanics</a>.</p></li><li><p><strong><a href="/MeanFieldHomogenization.jl/dev/manual/sensitivities#man-sensitivities">Sensitivities</a></strong> — differentiating an effective property with respect to a modulus, a fraction or a shape parameter, and which inclusion types can and cannot serve that.</p></li></ul><p>Finite elements appear twice in this package and the two are opposite: <a href="/MeanFieldHomogenization.jl/dev/manual/fe_inclusions#man-fe-inclusions">finite-element inclusions</a> are a solver called <em>inside</em> homogenization, while <a href="/MeanFieldHomogenization.jl/dev/fe_coupling/index#fe-coupling">finite-element coupling</a> is homogenization called inside a solver, as a constitutive law at a Gauss point.</p>',10)])])}const g=a(l,[["render",o]]);export{u as __pageData,g as default};
